    # 1. PRs created in Dec
    print("Fetching PRs...")
    prs = search_github("repo:cli/cli is:pr created:2024-12-01..2024-12-31")

    pr_total = len(prs)
    pr_merged = 0
    pr_closed = 0
    merge_times = []
    authors = {}

    for pr in prs:
        user = pr.get('user', {}).get('login')
        if user:
            authors[user] = authors.get(user, 0) + 1

        pr_details = pr.get('pull_request', {})
        merged_at_str = pr_details.get('merged_at')

        if merged_at_str:
            pr_merged += 1
            created_at = parse_time(pr['created_at'])
            merged_at = parse_time(merged_at_str)
            delta = merged_at - created_at
            merge_times.append(delta.total_seconds() / 86400.0)
        elif pr['state'] == 'closed':
            pr_closed += 1

    avg_merge_days = 0.0
    if merge_times:
        avg_merge_days = sum(merge_times) / len(merge_times)

    top_contributor = ""
    if authors:
        top_contributor = max(authors, key=authors.get)

    # 2. Issues created in Dec
    print("Fetching Created Issues...")
    issues_created = search_github("repo:cli/cli is:issue created:2024-12-01..2024-12-31")
    issue_total = len(issues_created)
    issue_bug_created = sum(1 for i in issues_created if is_bug(i))

    # 3. Issues closed in Dec
    print("Fetching Closed Issues...")
    issues_closed = search_github("repo:cli/cli is:issue closed:2024-12-01..2024-12-31")
    issue_bug_closed = sum(1 for i in issues_closed if is_bug(i))

    report = {
        "pr": {
            "total": pr_total,
            "merged": pr_merged,
            "closed": pr_closed,
            "avg_merge_days": round(avg_merge_days, 1),
            "top_contributor": top_contributor
        },
        "issue": {
            "total": issue_total,
            "bug": issue_bug_created,
            "resolved_bugs": issue_bug_closed
        }
    }

    print("Writing report...")
    with open('/app/report.json', 'w') as f:
        json.dump(report, f, indent=2)
    print("Done.")

if __name__ == "__main__":
    main()
EOF
